			let depthNdc: f32 = clamp((linearDepth - near) / (far - near), 0.0, 1.0);
			center.proj = vec4f(ndc, depthNdc, 1.0);
			center.projMat00 = uniform.fisheye_projMat00;
			center.projMat11 = fisheyeProjMat11;
